begin;
alter table public.apostolic_armies drop constraint apostolic_armies_status_check;
alter table public.apostolic_armies add constraint apostolic_armies_status_check check(status in('ready','marching','stationed','returning','attacking','besieging'));
create table public.apostolic_siege_machine_catalog(code text primary key,name text not null,description text not null,wall_damage integer not null check(wall_damage>=0),gate_damage integer not null check(gate_damage>=0),support integer not null check(support>=0),costs jsonb not null check(not(costs?'gems')),duration_seconds integer not null check(duration_seconds between 30 and 86400),sort_order smallint unique);
insert into public.apostolic_siege_machine_catalog values('battering_ram','Aríete','Rompe portões com impacto concentrado.',40,180,5,'{"cedar":120,"stone":40,"oil":25}',90,1),('catapult','Catapulta','Bombardeia muralhas à distância.',190,35,5,'{"cedar":150,"stone":180,"oil":35}',120,2),('siege_tower','Torre de Cerco','Protege a aproximação e amplia o poder do exército.',55,25,25,'{"cedar":240,"stone":70,"oil":45}',150,3);
create table public.apostolic_city_sieges(id uuid primary key default gen_random_uuid(),attacker_id uuid not null references public.profiles(id)on delete cascade,attacker_city_id uuid not null references public.apostolic_cities(id)on delete cascade,defender_city_id uuid not null references public.apostolic_cities(id)on delete cascade,army_id uuid not null references public.apostolic_armies(id)on delete restrict,machines jsonb not null check(jsonb_typeof(machines)='object'),phase text not null default'encampment'check(phase in('encampment','bombardment','breached','repelled')),round_no smallint not null default 0 check(round_no between 0 and 3),wall_hp integer not null check(wall_hp>=0),gate_hp integer not null check(gate_hp>=0),supply_wheat integer not null check(supply_wheat>0),started_at timestamptz not null default clock_timestamp(),next_phase_at timestamptz not null,finished_at timestamptz,idempotency_key uuid not null,unique(attacker_id,idempotency_key));
create unique index apostolic_one_active_siege_attacker_idx on public.apostolic_city_sieges(attacker_id)where phase in('encampment','bombardment');create unique index apostolic_one_active_siege_target_idx on public.apostolic_city_sieges(defender_city_id)where phase in('encampment','bombardment');
alter table public.apostolic_siege_machine_catalog enable row level security;alter table public.apostolic_city_sieges enable row level security;create policy siege_catalog_read on public.apostolic_siege_machine_catalog for select to authenticated using(true);create policy sieges_participants on public.apostolic_city_sieges for select to authenticated using(attacker_id=(select auth.uid())or exists(select 1 from public.apostolic_cities c where c.id=defender_city_id and c.owner_id=(select auth.uid())));revoke all on public.apostolic_siege_machine_catalog,public.apostolic_city_sieges from anon,authenticated;grant select on public.apostolic_siege_machine_catalog,public.apostolic_city_sieges to authenticated;
create or replace function public.apostolic_get_siege_center()returns jsonb language sql stable security definer set search_path=''as $$with own as(select id,province_id from public.apostolic_cities where owner_id=(select auth.uid()))select jsonb_build_object('unlocked',exists(select 1 from public.apostolic_city_research where city_id=(select id from own)and research_code='siege_engineering'),'machines',(select jsonb_agg(to_jsonb(m)order by sort_order)from public.apostolic_siege_machine_catalog m),'armies',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'total_units',total_units,'attack_power',attack_power,'status',status)),'[]'::jsonb)from public.apostolic_armies where owner_id=(select auth.uid())and status in('ready','stationed')),'targets',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'level',c.level,'slot',c.slot_no,'wall_level',w.level)order by c.slot_no),'[]'::jsonb)from public.apostolic_cities c join public.apostolic_city_buildings w on w.city_id=c.id and w.building='wall'where c.province_id=(select province_id from own)and c.id<>(select id from own)and not exists(select 1 from public.apostolic_city_attack_protections p where p.city_id=c.id and p.protected_until>clock_timestamp())),'active',(select to_jsonb(s)from(select x.id,x.phase,x.round_no,x.wall_hp,x.gate_hp,x.supply_wheat,x.next_phase_at,x.machines,c.name target_name from public.apostolic_city_sieges x join public.apostolic_cities c on c.id=x.defender_city_id where x.attacker_id=(select auth.uid())and x.phase in('encampment','bombardment')limit 1)s),'history',(select coalesce(jsonb_agg(to_jsonb(h)order by finished_at desc),'[]'::jsonb)from(select c.name target_name,s.phase,s.finished_at from public.apostolic_city_sieges s join public.apostolic_cities c on c.id=s.defender_city_id where s.attacker_id=(select auth.uid())and s.phase in('breached','repelled')order by s.finished_at desc limit 10)h))$$;
create or replace function public.apostolic_start_city_siege(p_army_id uuid,p_defender_city_id uuid,p_machines jsonb,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare uid uuid:=(select auth.uid());a public.apostolic_armies%rowtype;home public.apostolic_cities%rowtype;target public.apostolic_cities%rowtype;r record;qty integer;costs jsonb:='{}';k text;v bigint;duration integer:=60;supply integer;bal bigint;wall_level integer;begin if uid is null or p_idempotency_key is null or jsonb_typeof(p_machines)<>'object'then raise exception'invalid siege';end if;select*into a from public.apostolic_armies where id=p_army_id and owner_id=uid for update;if not found or a.status not in('ready','stationed')then raise exception'army unavailable';end if;select*into home from public.apostolic_cities where id=a.home_city_id;if not exists(select 1 from public.apostolic_city_research where city_id=home.id and research_code='siege_engineering')then raise exception'siege engineering required';end if;select*into target from public.apostolic_cities where id=p_defender_city_id and province_id=home.province_id and owner_id<>uid;if not found then raise exception'invalid target';end if;if exists(select 1 from public.apostolic_city_attack_protections where city_id=target.id and protected_until>clock_timestamp())then raise exception'target protected';end if;if exists(select 1 from public.apostolic_city_sieges where attacker_id=uid and idempotency_key=p_idempotency_key)then return public.apostolic_get_siege_center();end if;for r in select m.*,(e.value::text)::integer qty from jsonb_each(p_machines)e join public.apostolic_siege_machine_catalog m on m.code=e.key loop qty:=r.qty;if qty<0 or qty>10 then raise exception'invalid machine quantity';end if;duration:=greatest(duration,r.duration_seconds);for k,v in select key,(value::text)::bigint*qty from jsonb_each(r.costs)loop costs:=jsonb_set(costs,array[k],to_jsonb(coalesce((costs->>k)::bigint,0)+v),true);end loop;end loop;if not exists(select 1 from jsonb_each_text(p_machines)where value::integer>0)then raise exception'machines required';end if;supply:=greatest(30,a.total_units*2);costs:=jsonb_set(costs,'{wheat}',to_jsonb(coalesce((costs->>'wheat')::bigint,0)+supply),true);for k,v in select key,value::bigint from jsonb_each_text(costs)loop select amount into bal from public.apostolic_city_resources where city_id=home.id and resource=k for update;if coalesce(bal,0)<v then raise exception'insufficient resource: %',k;end if;end loop;for k,v in select key,value::bigint from jsonb_each_text(costs)loop update public.apostolic_city_resources set amount=amount-v where city_id=home.id and resource=k;insert into public.apostolic_resource_ledger(city_id,resource,delta,balance_after,reason,idempotency_key)select home.id,k,-v,amount,'city_siege',p_idempotency_key from public.apostolic_city_resources where city_id=home.id and resource=k;end loop;select level into wall_level from public.apostolic_city_buildings where city_id=target.id and building='wall';insert into public.apostolic_city_sieges(attacker_id,attacker_city_id,defender_city_id,army_id,machines,wall_hp,gate_hp,supply_wheat,next_phase_at,idempotency_key)values(uid,home.id,target.id,a.id,p_machines,wall_level*1000,wall_level*600,supply,clock_timestamp()+make_interval(secs=>duration),p_idempotency_key);update public.apostolic_armies set status='besieging'where id=a.id;return public.apostolic_get_siege_center();end;$$;
create or replace function public.apostolic_advance_city_siege(p_siege_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare s public.apostolic_city_sieges%rowtype;wall_damage integer;gate_damage integer;support integer;next_wall integer;next_gate integer;next_round integer;begin select*into s from public.apostolic_city_sieges where id=p_siege_id and attacker_id=(select auth.uid())for update;if not found or s.phase not in('encampment','bombardment')then raise exception'siege unavailable';end if;if s.next_phase_at>clock_timestamp()then raise exception'siege phase in progress';end if;select coalesce(sum(m.wall_damage*(e.value::text)::integer),0),coalesce(sum(m.gate_damage*(e.value::text)::integer),0),coalesce(sum(m.support*(e.value::text)::integer),0)into wall_damage,gate_damage,support from jsonb_each(s.machines)e join public.apostolic_siege_machine_catalog m on m.code=e.key;next_wall:=greatest(0,s.wall_hp-wall_damage-support);next_gate:=greatest(0,s.gate_hp-gate_damage);next_round:=s.round_no+1;if next_wall=0 or next_gate=0 then update public.apostolic_city_sieges set phase='breached',round_no=next_round,wall_hp=next_wall,gate_hp=next_gate,finished_at=clock_timestamp()where id=s.id;update public.apostolic_armies set status='ready'where id=s.army_id;elsif next_round>=3 then update public.apostolic_city_sieges set phase='repelled',round_no=next_round,wall_hp=next_wall,gate_hp=next_gate,finished_at=clock_timestamp()where id=s.id;update public.apostolic_armies set status='ready'where id=s.army_id;else update public.apostolic_city_sieges set phase='bombardment',round_no=next_round,wall_hp=next_wall,gate_hp=next_gate,next_phase_at=clock_timestamp()+interval'2 minutes'where id=s.id;end if;return public.apostolic_get_siege_center();end;$$;
revoke all on function public.apostolic_get_siege_center(),public.apostolic_start_city_siege(uuid,uuid,jsonb,uuid),public.apostolic_advance_city_siege(uuid)from public;grant execute on function public.apostolic_get_siege_center(),public.apostolic_start_city_siege(uuid,uuid,jsonb,uuid),public.apostolic_advance_city_siege(uuid)to authenticated;commit;
